// Compares the chat system prompt at HEAD with the working copy on the real chat model, with fake tools and records.
// Run: npx tsx --env-file=.env .qa/prompt-eval.ts [scenarioFilter]
import { execSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import { createOpenAI } from "@ai-sdk/openai";
import { generateText, stepCountIs, tool, type ModelMessage } from "ai";
import { z } from "zod";
import { iouInputSchema } from "@/lib/ai/iou-proposals";
import { transactionInputSchema } from "@/lib/ai/transaction-proposals";
import { balanceInputSchema } from "@/lib/ai/balance-proposals";
import { recurringInputSchema } from "@/lib/ai/recurring-proposals";
import { financeToolSchemas } from "@/lib/finance/tools";
import { netWorthInput } from "@/lib/finance/net-worth-source";
import { planInput } from "@/lib/ai/follow-ups";
import { agentDecisionSchema } from "@/lib/ai/agent-findings";

const openai = createOpenAI({ apiKey: process.env.OPENAI_API_KEY });
const TODAY = "2026-11-09";

function promptFrom(source: string) {
  const start = source.indexOf("export const SYSTEM_PROMPT = `") + "export const SYSTEM_PROMPT = `".length;
  return source.slice(start, source.indexOf("`;", source.indexOf("Keep the key figures in the text too.") > 0 ? source.indexOf("moneo-chart") : start)).replaceAll("\\`", "`");
}
function promptOf(source: string) {
  // The prompt ends at the first unescaped backtick after its start.
  const start = source.indexOf("export const SYSTEM_PROMPT = `") + "export const SYSTEM_PROMPT = `".length;
  let i = start;
  while (!(source[i] === "`" && source[i - 1] !== "\\")) i++;
  return source.slice(start, i).replaceAll("\\`", "`");
}
function descriptionsOf(...sources: string[]) {
  const map: Record<string, string> = {};
  for (const source of sources) for (const match of source.matchAll(/(\w+): tool\(\{\s*description: "((?:[^"\\]|\\.)*)"/g)) map[match[1]] = JSON.parse(`"${match[2]}"`);
  return map;
}
void promptFrom;

const versions = {
  old: { prompt: promptOf(execSync("git show HEAD:lib/ai/provider.ts").toString()),
    descriptions: descriptionsOf(execSync("git show HEAD:app/api/chat/route.ts").toString(), execSync("git show HEAD:lib/ai/investment-tools.ts").toString()), steps: 10, brief: false, fuzzy: false },
  new: { prompt: promptOf(readFileSync("lib/ai/provider.ts", "utf8")),
    descriptions: descriptionsOf(readFileSync("app/api/chat/route.ts", "utf8"), readFileSync("lib/ai/investment-tools.ts", "utf8")), steps: 30, brief: true, fuzzy: true },
};

const transactions = [
  { id: "t1", posted_on: "2026-11-07", description: "REWE Markt GmbH", amount_minor: "-4523" },
  { id: "t2", posted_on: "2026-11-05", description: "Netto Marken-Discount", amount_minor: "-1240" },
  { id: "t3", posted_on: "2026-11-01", description: "Miete November Hausverwaltung Schmidt", amount_minor: "-90000" },
  { id: "t4", posted_on: "2026-10-28", description: "Gehalt Oktober ACME GmbH", amount_minor: "320000" },
  { id: "t5", posted_on: "2026-10-20", description: "AMZN Mktp DE*7HQ2", amount_minor: "-1999" },
  { id: "t6", posted_on: "2026-10-15", description: "NETFLIX.COM", amount_minor: "-1399" },
  { id: "t7", posted_on: "2026-10-12", description: "Venjalin Ravindran Kino", amount_minor: "-2500" },
  { id: "t8", posted_on: "2026-09-28", description: "SEPA-Überweisung an Venjalin Ravindran", amount_minor: "-25000" },
  { id: "t9", posted_on: "2026-09-20", description: "AMZN Mktp DE*2K4LM", amount_minor: "-3499" },
  { id: "t10", posted_on: "2026-09-14", description: "Überweisung an Bilal Amin", amount_minor: "-5000" },
].map(row => ({ ...row, account: "Commerzbank Girokonto ••3500", currency_code: "EUR", status: "posted", kind: "ordinary",
  amountFormatted: `EUR ${(Math.abs(Number(row.amount_minor)) / 100).toFixed(2)}${Number(row.amount_minor) < 0 ? " out" : " in"}`, link: `/money/transactions?transaction=${row.id}` }));

const similar = (query: string, text: string) => {
  const q = query.toLowerCase(), words = text.toLowerCase().split(/[^\p{L}\p{N}]+/u);
  return words.some(word => word.length >= 3 && (word.startsWith(q.slice(0, 4)) || q.startsWith(word.slice(0, 4))));
};
function search(input: z.infer<typeof financeToolSchemas.searchInput>, fuzzy: boolean) {
  const filtered = transactions.filter(row => (!input.from || row.posted_on >= input.from) && (!input.to || row.posted_on <= input.to)
    && (!input.minAmountMinor || Math.abs(Number(row.amount_minor)) >= Number(input.minAmountMinor)) && (!input.maxAmountMinor || Math.abs(Number(row.amount_minor)) <= Number(input.maxAmountMinor)));
  if (!input.query) return filtered.slice(0, input.limit ?? 20);
  const exact = filtered.filter(row => row.description.toLowerCase().includes(input.query!.toLowerCase())).map(row => ({ ...row, match: "text" }));
  const close = fuzzy ? filtered.filter(row => !exact.some(e => e.id === row.id) && similar(input.query!, row.description)).map(row => ({ ...row, match: "similar_name" })) : [];
  return [...exact, ...close].slice(0, input.limit ?? 20).map(row => fuzzy ? row : (({ match: _m, ...rest }) => rest)(row as typeof row & { match?: string }));
}

const wealth = { items: [{ id: "w1", group: "lent", name: "Lent to Bilal Amin", person: "Bilal Amin", amountFormatted: "EUR 100.00", currencyCode: "EUR", asOf: "2026-08-02" },
  { id: "w2", group: "asset", name: "Car", amountFormatted: "EUR 8,000.00", currencyCode: "EUR", asOf: "2026-06-01" }], link: "/money/wealth" };
const BRIEF = `Accounts: Cash EUR (cash, EUR); Commerzbank Girokonto ••3500 (checking, EUR)
People with open loans: Bilal Amin: owes you EUR 100.00 (since 2026-08-02)
Recurring payments: Netflix: EUR 13.99 out, monthly; Rent: EUR 900.00 out, monthly; Salary ACME: EUR 3,200.00 in, monthly`;

const loose = z.object({}).passthrough();
const schemas: Record<string, z.ZodType> = { iou_propose: iouInputSchema, transaction_propose: transactionInputSchema, balance_propose: balanceInputSchema,
  recurring_propose: recurringInputSchema, transactions_search: financeToolSchemas.searchInput, net_worth: netWorthInput, plan_investigation: planInput,
  agents_decide: agentDecisionSchema, analytics_cashflow: financeToolSchemas.periodInput };
const card = { proposed: "card", note: "A card with Add and Dismiss is shown to the user below your answer. Say it is waiting for their approval; do not repeat the details." };
function output(name: string, input: Record<string, unknown>, fuzzy: boolean): unknown {
  switch (name) {
    case "transactions_search": return search(input as never, fuzzy);
    case "wealth_list": return wealth;
    case "accounts_list": return [{ name: "Commerzbank Girokonto ••3500", type: "checking", currency_code: "EUR" }, { name: "Cash EUR", type: "cash", currency_code: "EUR" }];
    case "accounts_getBalances": return [{ account: "Commerzbank Girokonto ••3500", balanceFormatted: "EUR 2,410.55", asOf: TODAY }, { account: "Cash EUR", balanceFormatted: "EUR 80.00", asOf: "2026-11-01" }];
    case "net_worth": return { totalFormatted: "EUR 10,590.55", parts: [{ name: "Accounts", amountFormatted: "EUR 2,490.55" }, { name: "Wealth", amountFormatted: "EUR 8,100.00" }], leftOut: [], link: "/money/wealth" };
    case "analytics_cashflow": return { from: input.from, to: input.to, currencyCode: "EUR", spendingFormatted: "EUR 1,032.71", incomeFormatted: "EUR 3,200.00", byCategory: [{ name: "Rent", amountFormatted: "EUR 900.00", amountMinor: "90000" }, { name: "Groceries", amountFormatted: "EUR 57.63", amountMinor: "5763" }, { name: "Shopping", amountFormatted: "EUR 19.99", amountMinor: "1999" }, { name: "Subscriptions", amountFormatted: "EUR 13.99", amountMinor: "1399" }, { name: "Entertainment", amountFormatted: "EUR 25.00", amountMinor: "2500" }] };
    case "finance_investigate": return { interpretedFilters: input, rows: [{ group: "Rent", amountFormatted: "EUR 900.00", amountMinor: "90000" }, { group: "Groceries", amountFormatted: "EUR 57.63", amountMinor: "5763" }, { group: "Shopping", amountFormatted: "EUR 54.98", amountMinor: "5498" }], link: "/money/transactions" };
    case "finance_entities": return { accounts: ["Commerzbank Girokonto ••3500", "Cash EUR"], categories: ["Rent", "Groceries", "Shopping", "Subscriptions", "Entertainment"], merchants: ["REWE", "Netto", "Amazon", "Netflix"] };
    case "recurring_list": return { schedules: [{ id: "r1", name: "Netflix", amount: "EUR 13.99", direction: "out", cadence: "monthly", next: "2026-11-15" }, { id: "r2", name: "Rent", amount: "EUR 900.00", direction: "out", cadence: "monthly", next: "2026-12-01" }], suggestions: [] };
    case "iou_findRepayments": return { found: [], note: "No new repayments found." };
    case "agents_findings": return { proposals: [{ id: "p1", kind: "categorization", title: "Categorize 3 AMZN Mktp payments as Shopping" }] };
    case "app_help": return { guide: "Import (/import): upload bank statements (CSV, PDF) or connect a bank. Money (/money): accounts, transactions, Wealth, recurring. Plan (/plan): budgets and goals. Artifacts (/artifacts): interactive pages." };
    case "suggest_artifact": return { href: "/artifacts/new?request=1" };
    case "goals_list": return [{ name: "Emergency fund", targetFormatted: "EUR 5,000.00", target_date: "2027-06-01" }];
    case "forecast_evaluate": return { status: "ok", availableToSpendFormatted: "EUR 1,210.55" };
    case "investments_portfolio": return { positions: [{ name: "Vanguard FTSE All-World (VWCE)", valueFormatted: "EUR 4,120.00", gainFormatted: "EUR 412.00" }], cashFormatted: "EUR 300.00" };
    case "investments_security": return { results: [{ name: "Vanguard FTSE All-World UCITS ETF (Acc)", isin: "IE00BK5BQT80", priceFormatted: "EUR 132.10" }] };
    case "investments_order": return { proposed: "Buy EUR 100.00 of VWCE", note: "A card with Scalable's preview is shown; the user taps to place it." };
    case "plan_investigation": return { shown: true };
    default: return name.endsWith("_propose") || name === "agents_decide" ? card : { note: "No data in this test." };
  }
}

type Call = { name: string; input: Record<string, unknown> };
type Scenario = { id: string; history?: ModelMessage[]; message: string; check: (calls: Call[], text: string) => string[] };
const called = (calls: Call[], name: string) => calls.filter(call => call.name === name);
const need = (ok: boolean, problem: string) => ok ? [] : [problem];
const scenarios: Scenario[] = [
  { id: "loan-nickname", message: "i gave 250 eurs to venji", check: (calls, text) => [
    ...need(called(calls, "transactions_search").length > 0, "did not search transactions"),
    ...need(called(calls, "iou_propose").some(call => call.input.date === "2026-09-28"), "loan card not dated 2026-09-28 from the transfer"),
    ...need(/venjalin/i.test(text), "did not name the matched person") ] },
  { id: "loan-correction", history: [{ role: "user", content: "I lent 50 to Bilal" }, { role: "assistant", content: "I've prepared a card for it. It's waiting for your approval.\n\nBilal owes you EUR 50.00 · Lent on 2026-11-09." }],
    message: "his name is Bilal Amin, it was in september", check: calls => need(called(calls, "iou_propose").some(call => /bilal amin/i.test(String(call.input.person)) && String(call.input.date).startsWith("2026-09")), "no corrected Bilal Amin card dated September") },
  { id: "loan-already-recorded", message: "I lent Bilal 100 euros back in August", check: (calls, text) => [
    ...need(called(calls, "iou_propose").length === 0 || /already/i.test(text), "proposed a duplicate without saying it's already recorded"),
    ...need(/already|recorded|wealth/i.test(text), "did not mention the existing loan") ] },
  { id: "spend-one", message: "btw I spent 12.40 at Netto", check: calls => need(called(calls, "transaction_propose").some(call => String(call.input.amount).replace(/\.?0+$/, "") === "12.4"), "no 12.40 transaction card") },
  { id: "spend-three", message: "5 on coffee, 7 on lunch and 10 on a taxi", check: calls => need(called(calls, "transaction_propose").length === 3, `expected 3 transaction cards, got ${called(calls, "transaction_propose").length}`) },
  { id: "balance", message: "I have 115 in cash", check: calls => need(called(calls, "balance_propose").some(call => String(call.input.amount) === "115"), "no 115 balance card") },
  { id: "net-worth", message: "what's my net worth?", check: (calls, text) => [...need(called(calls, "net_worth").length > 0, "did not call net_worth"), ...need(text.includes("10,590.55"), "did not quote the total")] },
  { id: "spending-month", message: "how much did I spend in october?", check: calls => need(called(calls, "analytics_cashflow").length + called(calls, "finance_investigate").length > 0, "no cashflow/investigate call") },
  { id: "repayments", message: "did venji pay me back yet?", check: calls => need(called(calls, "iou_findRepayments").length > 0, "did not call iou_findRepayments") },
  { id: "lent-list", message: "how much have I lent and to whom?", check: (calls, text) => [...need(called(calls, "wealth_list").length > 0 || /bilal/i.test(text), "no wealth lookup"), ...need(/bilal/i.test(text), "did not name Bilal")] },
  { id: "amazon-fuzzy", message: "how much did I spend on amazon since september?", check: (calls, text) => need(/54\.98|34\.99.*19\.99|19\.99.*34\.99/.test(text), "did not find both AMZN payments") },
  { id: "recurring-cancel", message: "remove netflix from my recurring payments", check: calls => [...need(called(calls, "recurring_list").length > 0, "did not list recurring first"), ...need(called(calls, "recurring_propose").length > 0, "no recurring card")] },
  { id: "agents", message: "what did the agent team find?", check: calls => need(called(calls, "agents_findings").length > 0, "did not call agents_findings") },
  { id: "app-help", message: "where do I upload a bank statement?", check: (calls, text) => need(called(calls, "app_help").length > 0 || text.includes("/import"), "no app_help and no /import") },
  { id: "artifact", message: "build me a savings simulator", check: calls => need(called(calls, "suggest_artifact").length > 0, "did not call suggest_artifact") },
  { id: "chart", message: "show my october spending by category as a chart", check: (_calls, text) => need(text.includes("```moneo-chart"), "no moneo-chart block") },
  { id: "invest-buy", message: "buy 100 euros of VWCE", check: (calls, text) => [...need(called(calls, "investments_order").length > 0, "no order card"), ...need(!/\b(placed|bought|executed)\b/i.test(text) || /tap|approv|confirm/i.test(text), "claims the order was placed")] },
  { id: "german", message: "Wie viel habe ich im Oktober ausgegeben?", check: (_calls, text) => need(/\b(du|hast|ausgegeben|im Oktober)\b/i.test(text), "did not reply in German") },
];

async function run(version: keyof typeof versions, scenario: Scenario) {
  const v = versions[version];
  const calls: Call[] = [];
  const tools = Object.fromEntries(Object.entries(v.descriptions).map(([name, description]) => [name, tool({ description, inputSchema: (schemas[name] ?? loose) as z.ZodType<Record<string, unknown>>,
    execute: async (input: Record<string, unknown>) => { calls.push({ name, input }); return output(name, input, v.fuzzy); } })]));
  const instructions = `${v.prompt}\n\n${v.brief ? `# About the owner\nToday is ${TODAY} (Europe/Berlin); display currency EUR.\n${BRIEF}\n\n` : `Today is ${TODAY} (Europe/Berlin); display currency EUR. `}UI context is only a navigation hint, never authorization. Do not change records; for a category change request, use the selection preview.`;
  const started = Date.now();
  const result = await generateText({ model: openai("gpt-6.1-sol"), system: instructions, messages: [...(scenario.history ?? []), { role: "user", content: scenario.message }],
    tools, stopWhen: stepCountIs(v.steps), maxOutputTokens: 3000, providerOptions: { openai: { reasoningEffort: "low" } } });
  return { version, id: scenario.id, problems: scenario.check(calls, result.text), calls: calls.map(call => `${call.name}(${JSON.stringify(call.input)})`), text: result.text, steps: result.steps.length, ms: Date.now() - started };
}

const filter = process.argv[2];
const chosen = scenarios.filter(s => !filter || s.id.includes(filter));
const results = await Promise.all(chosen.flatMap(scenario => (["old", "new"] as const).map(version => run(version, scenario).catch(error => ({ version, id: scenario.id, problems: [`error: ${error.message}`], calls: [], text: "", steps: 0, ms: 0 })))));
writeFileSync(".qa/prompt-eval-results.json", JSON.stringify(results, null, 2));
for (const scenario of chosen) {
  const [old, next] = (["old", "new"] as const).map(version => results.find(r => r.id === scenario.id && r.version === version)!);
  console.log(`${scenario.id.padEnd(22)} old ${old.problems.length ? "FAIL" : "pass"} (${old.steps} steps, ${(old.ms / 1000).toFixed(1)}s)  new ${next.problems.length ? "FAIL" : "pass"} (${next.steps} steps, ${(next.ms / 1000).toFixed(1)}s)${[...old.problems.map(p => `\n   old: ${p}`), ...next.problems.map(p => `\n   new: ${p}`)].join("")}`);
}

